const icons={'科学':'✺','技术':'⌘','艺术':'❋','生活':'☕','自然':'❀','故事':'✧','奇怪知识':'☄','游戏':'♞','绘画与书画':'▧','古董与珠宝':'♜','古币与钱币':'◉','古代文明':'⌘','雕塑与宗教艺术':'☼','陶瓷与器物':'◍','古籍与手稿':'▤','历史文物':'⚒','科技与发明':'⌘','AI与机器人':'⌬','航天与宇宙':'✧','自然与化石':'✺','矿物与宝石':'◇','建筑与设计':'▦','时尚与潮流':'✦','摄影与影像':'▧','游戏与交互':'♞','互联网奇物':'☄','流行文化':'♫','音乐与声音':'♫','生活发现':'☕','原创理论':'∞','其他':'✦'};
