const titles={catalog:'功能地图',archaeology:'万物文明考古局',heritage:'万界遗产交换站',embassies:'万界文明大使馆',civilizations:'万物文明演化实验室',collision:'万物碰撞机',mysteries:'万物谜案馆',living:'万物活体博物馆',coexhibitions:'万物联合展厅',parallel:'万物平行宇宙',constellation:'万物星图',discover:'发现广场',search:'搜索万物',museum:'我的博物馆',saved:'心动收藏',journey:'跨界探索',notifications:'通知中心',profile:'馆长主页',memories:'回忆剧场','world-museums':'世界名馆','wonder-radar':'万物雷达',insights:'功能热度',culture:'当代新奇',fantasy:'玄幻异界','virtual-gallery':'展厅工坊',cosmos:'万物时光',lab:'万物实验室',play:'万物皆可玩',wheels:'万物转盘',adventure:'万物命运接力'};
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3000)}
async function api(path,{method='GET',body,form}={}){
  const options={method,credentials:'same-origin',headers:{}};
  if(body!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}
  if(form)options.body=form;
  let r;try{r=await fetch('/api'+path,options)}catch(e){throw Error('无法连接服务器。请确认已启动后端，而不是直接双击 HTML。')}
  const ct=r.headers.get('content-type')||'';let data=ct.includes('json')?await r.json():await r.text();
  if(!r.ok){let detail=data?.detail||data||'请求失败';if(Array.isArray(detail))detail=detail.map(x=>x.msg).join('；');throw Error(detail)}
  return data;
}
const usageFeatureByView={catalog:'feature_map',archaeology:'fantasy_realms',heritage:'collaboration',embassies:'collaboration',civilizations:'fantasy_realms',collision:'everything_lab',mysteries:'interactive_lab',living:'discover',coexhibitions:'collaboration',parallel:'collaboration',discover:'discover',search:'discover','world-museums':'world_museums','wonder-radar':'tech_radar',insights:'insights',memories:'memories',museum:'hall_builder',journey:'atlas_explore',features:'personal_world',saved:'discover',notifications:'discover',profile:'discover',culture:'modern_culture',fantasy:'fantasy_realms','virtual-gallery':'virtual_gallery',cosmos:'world_time',lab:'everything_lab',play:'interactive_lab',wheels:'interactive_lab',adventure:'interactive_lab'};
function trackUsage(feature,action='open'){if(!S.user)return Promise.resolve();return api('/insights/event',{method:'POST',body:{feature,action}}).catch(()=>{});}
window.WonderAnalytics={track:trackUsage};
function mustLogin(){if(S.user)return true;openAuth('login');toast('登录后才能继续');return false}
function categoryGlyph(item){return icons[item.category]||'✦'}
function art(item,extra=''){const cls=classes[item.category]||'cat-odd';return `<div class="card-art ${cls} ${extra}"><span class="glyph">${categoryGlyph(item)}</span>${item.image_url?`<img src="${E(item.image_url)}" loading="lazy" alt="${E(item.title)}">`:''}<span class="badge">${E(item.category||'其他')}</span></div>`}
function card(item){return `<article class="card" tabindex="0" data-action="detail" data-id="${item.id}">${art(item)}<div class="card-content"><div class="eyebrow">OBJECT / ${String(item.id).padStart(5,'0')} · ${E(TAX.seriesLabels?.[item.series||'民间奇趣']||item.series||'民间奇趣')}</div><h3>${E(item.title)}</h3><p>${E(item.description||item.story||'这件展品还没有介绍。')}</p><div class="card-taxonomy"><button type="button" data-action="filterDomain" data-value="${E(item.domain||'其他')}" title="查看这个领域">${E(item.domain||'其他')}</button><button type="button" data-action="filterCategory" data-value="${E(item.category||'其他')}" data-domain="${E(item.domain||'其他')}" title="查看这个细分类别">${E(item.category||'其他')}</button><button type="button" data-action="filterTime" data-value="${E(item.time_bucket||'时间不详')}" title="查看这个年代">${E(item.time_bucket||'时间不详')}</button></div><div class="card-bottom"><span>◎ ${E(item.owner||S.user?.username||'未知馆长')}</span><span>♡ ${item.likes_count||0}　⌁ ${item.comments_count||0}</span></div></div></article>`}
const WHEEL_CONTEXTS={
 food:{icon:'🍜',label:'吃什么'},
 travel:{icon:'🧭',label:'去哪玩'},
 watch:{icon:'🎬',label:'看什么'},
 read:{icon:'📚',label:'读什么'},
 study:{icon:'🧠',label:'学什么'},
 exercise:{icon:'🏃',label:'怎么运动'},
 activity:{icon:'🎲',label:'做什么'},
 custom:{icon:'✦',label:'自定义'}
};
function suggestWheelTopic(x){
 const tags=Array.isArray(x?.tags)?x.tags.join(' '):(x?.tags||'');
 const meta=[x?.title,x?.category,x?.domain,tags].join(' ').toLowerCase();
 const rules=[
  ['food',/美食|食物|饮食|餐饮|料理|菜谱|小吃|米线|菌子|牛排|烧烤|火锅|烤鱼|面条|饺子|包子|米饭|水果|甜品|蛋糕|奶茶|咖啡|茶饮|饮料|零食|巧克力|冰粉|鲜花饼|food|recipe|cuisine|dessert|steak|pizza|sushi|ramen|fruit/],
  ['travel',/旅游|旅行|游记|景点|徒步|古镇|城市漫步|地理|国家公园|山川|湖泊|海岸|博物馆建筑|旅行路线|travel|tourism|landscape|destination/],
  ['watch',/电影|影评|影视|纪录片|动画|动漫|电视剧|剧集|电影海报|film|movie|cinema|anime|documentary/],
  ['read',/书籍|阅读|小说|文学|古籍|诗歌|传记|漫画|书评|散文|图书|book|novel|literature|poetry/],
  ['study',/教程|课程|教科书|编程|算法|数学|物理|化学|计算机|人工智能|课程笔记|学习方法|coding|calculus|programming|algorithm/],
  ['exercise',/健身|跑步|篮球|足球|游泳|羽毛球|网球|骑行|体能|运动|瑜伽|拉伸|running|fitness|basketball|cycling/],
  ['activity',/桌游|小游戏|手工|摄影|绘画|活动|挑战|创作体验|游戏与交互|craft|gameplay|hobby/]
 ];
 return rules.find(([key,pattern])=>pattern.test(meta))?.[0]||'custom';
}
function wheelActions(x){
 const suggested=suggestWheelTopic(x),best=WHEEL_CONTEXTS[suggested];
 const choices=Object.entries(WHEEL_CONTEXTS).map(([key,d])=>
  '<button class="ghost" data-action="wheelFrom" data-id="'+x.id+'" data-topic="'+key+'">'+d.icon+' '+d.label+'</button>').join('');
 return '<div class="detail-wheel-actions">'+
 '<button class="primary" data-action="wheelFrom" data-topic="'+suggested+'" data-id="'+x.id+'">'+
 best.icon+' 一键加入「'+best.label+'」转盘</button>'+
 '<details class="detail-wheel-more"><summary>↔ 放到其他类型的转盘</summary>'+
 '<div class="detail-wheel-options">'+choices+'</div>'+
 '<p>分类来自藏品标题与标签的提示，不是自动鉴定。你可以自行选择任意转盘。</p></details></div>';
}
function empty(heading,text='',action=''){return `<div class="empty"><b>${E(heading)}</b><p>${E(text)}</p>${action}</div>`}
function heading(e,h,p=''){return `<div class="section-title"><div><div class="eyebrow">${e}</div><h2>${h}</h2><p>${p}</p></div></div>`}
function usageGuide(title,steps){return `<section class="usage-guide"><div class="usage-guide-title"><span>HOW IT WORKS</span><b>${title}</b></div><div class="usage-guide-steps">${steps.map((x,i)=>`<div><i>${i+1}</i><span>${E(x)}</span></div>`).join('')}</div></section>`}
function navMark(){document.querySelectorAll('.sidebar [data-action="navigate"],.mobile-nav [data-action="navigate"]').forEach(b=>b.classList.toggle('active',b.dataset.view===S.view));const activeSide=document.querySelector('.sidebar [data-action="navigate"].active');const activeGroup=activeSide?.closest('details.nav-group');if(activeGroup)activeGroup.open=true;$('#pageCrumb').textContent=titles[S.view]||'发现广场';const section=$('#pageSection');if(section)section.textContent=window.WonderFeatureMap?.groupFor(S.view)||'万物博物馆';const back=$('#navBack');if(back)back.hidden=!S.navHistory.length;const label=S.user?`◈ ${S.user.username} · 已连接`: '未登录 · 游客漫游中';$('#sideUser').textContent=label;$('#loginTop').textContent=S.user?`◈ ${S.user.username}`:'登录 / 注册';$('#loginTop').dataset.action=S.user?'account':'login';}
async function init(){try{S.user=(await api('/me')).user;if(new URLSearchParams(location.search).get('search')){WonderSearch.setQuery(new URLSearchParams(location.search).get('search'));S.view='search'}if(new URLSearchParams(location.search).has('archaeology')){const ar=Number(new URLSearchParams(location.search).get('archaeology'));if(Number.isSafeInteger(ar)&&ar>0){S.view='archaeology';window.WonderArchaeology?.open(ar)}}if(new URLSearchParams(location.search).has('heritage')){const hid=Number(new URLSearchParams(location.search).get('heritage'));if(Number.isSafeInteger(hid)&&hid>0){S.view='heritage';window.WonderHeritage?.open(hid)}}if(new URLSearchParams(location.search).has('embassy')){const eid=Number(new URLSearchParams(location.search).get('embassy'));if(Number.isSafeInteger(eid)&&eid>0){S.view='embassies';window.WonderEmbassies?.open(eid)}}if(new URLSearchParams(location.search).has('civilization')){const civ=Number(new URLSearchParams(location.search).get('civilization'));if(Number.isSafeInteger(civ)&&civ>0){S.view='civilizations';window.WonderCivilizations?.open(civ)}}if(new URLSearchParams(location.search).has('collision')){const cid=Number(new URLSearchParams(location.search).get('collision'));if(Number.isSafeInteger(cid)&&cid>0){S.view='collision';window.WonderCollision?.open(cid)}}if(new URLSearchParams(location.search).has('mystery')){const quest=Number(new URLSearchParams(location.search).get('mystery'));if(Number.isSafeInteger(quest)&&quest>0){S.view='mysteries';window.WonderMysteries?.open(quest)}}if(new URLSearchParams(location.search).has('living')){const live=Number(new URLSearchParams(location.search).get('living'));if(Number.isSafeInteger(live)&&live>0){S.view='living';window.WonderLiving?.open(live)}}if(new URLSearchParams(location.search).has('coexhibition')){const shared=Number(new URLSearchParams(location.search).get('coexhibition'));if(Number.isSafeInteger(shared)&&shared>0){S.view='coexhibitions';window.WonderCoExhibitions?.open(shared)}}if(new URLSearchParams(location.search).has('atlas_start')){S.view='journey';await WonderAtlas.activateShared()}navMark();await render();window.WonderFeatureMap?.remember(S.view);const query=new URLSearchParams(location.search);const sourceId=Number(query.get('source'));if(Number.isSafeInteger(sourceId)&&sourceId>0){openDetail(sourceId).catch(()=>toast('原始馆藏可能已经撤回。'));}if(S.user){refreshUnread();trackUsage(S.view==='journey'?'atlas_explore':'discover','open')}}catch(e){$('#main').innerHTML=empty('连接失败',e.message,'<button class="primary" data-action="reload">重新连接</button>')}}
async function refreshUnread(){if(!S.user){$('#navUnread').textContent='';return}try{let n=await api('/notifications');$('#navUnread').textContent=n.unread||''}catch(e){}}
async function navigate(view,options={}){if(!view)return;if(view!==S.view&&options.history!==false){S.navHistory.push(S.view);if(S.navHistory.length>40)S.navHistory.shift();}if(view!=='wheels')window.WonderWheel?.stop();if(view!=='adventure')window.WonderAdventure?.stop();if(view!=='play')window.WonderPlay?.stop();if(view!=='memories'&&window.WonderMemories)WonderMemories.stop();if(view!=='virtual-gallery')window.WonderGallery3D?.dispose();S.view=view;S.page=1;navMark();if(usageFeatureByView[view])trackUsage(usageFeatureByView[view],'open');await render();window.WonderFeatureMap?.remember(view);window.scrollTo({top:0,behavior:'smooth'})}
async function navBack(){const previous=S.navHistory.pop();if(previous)await navigate(previous,{history:false});else if(S.view!=='discover')await navigate('discover',{history:false});else toast('已经在发现广场了');navMark();}
function renderNextSteps(view){if(view==='catalog')return '';const items=window.WonderFeatureMap?.nextSteps(view)||[];if(!items.length)return '';return '<section class="next-steps"><div class="next-steps-heading"><div><div class="eyebrow">KEEP EXPLORING</div><h2>从这里继续</h2><p>这些功能与当前内容有直接关系，可以沿着一条清晰的路径继续探索。</p></div><button class="ghost" data-action="navigate" data-view="catalog">全部功能 ↗</button></div><div class="next-steps-grid">'+items.map(x=>'<button class="next-step-card" data-action="navigate" data-view="'+E(x.view)+'"><span>'+x.icon+'</span><b>'+E(x.title)+'</b><small>'+E(x.reason)+'</small><i>继续 ↗</i></button>').join('')+'</div></section>'}
async function render(){try{let h='';if(S.view==='catalog')h=window.WonderFeatureMap.render();else if(S.view==='discover')h=await discover();else if(S.view==='search')h=await WonderSearch.render();else if(S.view==='museum')h=await museum();else if(S.view==='saved')h=await saved();else if(S.view==='journey')h=await WonderAtlas.render();else if(S.view==='notifications')h=await notifications();else if(S.view==='profile')h=await profile();else if(S.view==='memories')h=await WonderMemories.render();else if(S.view==='constellation')h=await WonderConstellation.render();else if(S.view==='parallel')h=await WonderParallel.render();else if(S.view==='coexhibitions')h=await WonderCoExhibitions.render();else if(S.view==='living')h=await WonderLiving.render();else if(S.view==='mysteries')h=await WonderMysteries.render();else if(S.view==='collision')h=await WonderCollision.render();else if(S.view==='civilizations')h=await WonderCivilizations.render();else if(S.view==='embassies')h=await WonderEmbassies.render();else if(S.view==='heritage')h=await WonderHeritage.render();else if(S.view==='archaeology')h=await WonderArchaeology.render();else if(S.view==='world-museums')h=await WorldMuseums.render();else if(S.view==='wonder-radar')h=await WonderDiscovery.render();else if(S.view==='insights')h=await WonderDiscovery.renderInsights();else if(S.view==='culture')h=await WonderCulture.render();else if(S.view==='fantasy')h=await WonderFantasy.render();else if(S.view==='virtual-gallery')h=await WonderGallery.render();else if(S.view==='cosmos')h=await WonderCosmos.render();else if(S.view==='lab')h=await WonderLab.render();else if(S.view==='lab')h=await WonderLab.render();else if(S.view==='play')h=await WonderPlay.render();else if(S.view==='wheels')h=await WonderWheel.render();else if(S.view==='adventure')h=await WonderAdventure.render();if(S.view!=='catalog')h+=renderNextSteps(S.view);$('#main').innerHTML=h;if(S.view==='play')requestAnimationFrame(()=>WonderPlay.afterMount())}catch(e){$('#main').innerHTML=empty('暂时无法打开',e.message,'<button class="ghost" data-action="reload">重试</button>')}}
async function discover(){const [stat,feed]=await Promise.all([api('/stats'),api(`/feed?q=${encodeURIComponent(S.q)}&category=${encodeURIComponent(S.cat)}&domain=${encodeURIComponent(S.domain)}&series=${encodeURIComponent(S.series)}&time_bucket=${encodeURIComponent(S.timeBucket)}&sort=${S.sort}&page=${S.page}&following=${S.following}`)]);S.items=feed.items;return `
<section class="hero"><div class="hero-copy"><div class="eyebrow">✧ EXPLORE THE UNEXPECTED · 万物开放收藏计划</div><h1>世界很大，<br><span>万物皆可收藏。</span></h1><p>发现一件有趣的事物，或把自己的奇思妙想放进展柜。不同的馆长正在这里共同建造一座没有边界的博物馆。</p><div class="hero-buttons"><button class="primary" data-action="new">＋ 分享我的发现</button><button class="ghost" data-action="navigate" data-view="search">⌕ 搜索万物</button><button class="ghost" data-action="navigate" data-view="catalog">功能地图</button><button class="ghost" data-action="navigate" data-view="journey">✧ 随机奇遇</button><button class="ghost" data-action="navigate" data-view="wheels">🎡 万物转盘</button></div></div><div class="cosmos"><div class="planet"></div></div></section>
<div class="stats"><div class="stat"><strong>${stat.exhibits}</strong> 件公开展品</div><div class="stat"><strong>${stat.curators}</strong> 位真实馆长</div><div class="stat"><strong>${stat.halls}</strong> 座开放展厅</div></div>
<section class="wm-discover-promo"><div><div class="eyebrow">NEW · WORLD MUSEUM COLLECTION</div><h2>不必等别人上传，世界名作已经在这里。</h2><p>从大都会、芝加哥与克利夫兰艺术博物馆的开放馆藏出发，发现真实作品，再收入自己的博物馆。</p></div><button class="primary" data-action="navigate" data-view="world-museums">进入世界名馆 ↗</button></section>
${usageGuide('发现广场怎么逛',['用分类或搜索找展品，也可以按最新/热门排序。','点击卡片查看完整档案；登录后可点赞、评论、收藏或关注馆长。','发布内容时选择公开或私密；只有公开展品会出现在公共广场。'])}
${heading('CURATED BY THE WORLD','来自世界的发现','这里展示的是用户真正发布的公开展品，没有虚构的社区内容。')}
<section class="v6-discovery-promo"><button data-action="navigate" data-view="wonder-radar"><span>✧</span><b>万物雷达</b><small>AI、机器人、太空与互联网奇物</small><i>去探索 ↗</i></button><button data-action="navigate" data-view="insights"><span>▥</span><b>功能热度</b><small>看看大家真正喜欢什么，再决定开发优先级</small><i>查看统计 ↗</i></button></section>
<section class="v9-discovery-promo"><button data-action="navigate" data-view="culture"><span>♫</span><b>当代新奇</b><small>热梗、数码产品、游戏与新科技，放在同一个探索入口</small><i>发现新东西 ↗</i></button><button data-action="navigate" data-view="virtual-gallery"><span>▧</span><b>展厅工坊</b><small>选择原创免费图纸，设计展厅，进入沉浸漫游</small><i>建造我的世界 ↗</i></button></section>
<div class="series-switcher" role="group" aria-label="内容大系列">${['全部',...TAX.series].map(v=>`<button type="button" class="series-tab ${S.series===v?'active':''}" data-action="series" data-series="${E(v)}">${E(TAX.seriesLabels?.[v]||v)}</button>`).join('')}</div><p class="taxonomy-intro">先选内容系列，再按领域、细分类别和时代交叉筛选；同一件展品可以同时拥有多个维度。</p><form class="controls" id="searchForm"><div class="filters"><button type="button" class="chip ${S.following?'active':''}" data-action="following">♡ 关注动态</button>${quickCategories.map(c=>`<button type="button" class="chip ${S.cat===c?'active':''}" data-action="category" data-cat="${E(c)}">${E(c)}</button>`).join('')}<select class="sort" name="categoryFilter" aria-label="更多分类">${categories.map(c=>`<option value="${E(c)}" ${S.cat===c?'selected':''}>${c==='全部'?'全部分类':E(c)}</option>`).join('')}</select><select class="sort" name="domainFilter" aria-label="主要领域"><option value="全部">全部领域</option>${TAX.domains.map(d=>`<option value="${E(d)}" ${S.domain===d?'selected':''}>${E(d)}</option>`).join('')}</select><select class="sort" name="timeBucketFilter" aria-label="时代"><option value="全部">全部时代</option>${TAX.timeBuckets.map(t=>`<option value="${E(t)}" ${S.timeBucket===t?'selected':''} title="${E(TAX.timeDescriptions[t]||'')}">${E(t)}</option>`).join('')}</select></div><div class="head-actions"><input class="field-inline" name="q" value="${E(S.q)}" placeholder="搜索藏品、标签、馆长…" aria-label="搜索"><button class="ghost" type="submit">⌕ 搜索</button><select class="sort" name="sort" aria-label="排序"><option value="latest" ${S.sort==='latest'?'selected':''}>最新发布</option><option value="popular" ${S.sort==='popular'?'selected':''}>最受欢迎</option></select></div></form>
${S.items.length?`<div class="card-grid">${S.items.map(card).join('')}</div>`:empty('展柜还很空','成为第一个留下发现的馆长吧。','<button class="primary" data-action="new">发布第一件展品</button>')}
${S.items.length===24?`<button class="ghost more" data-action="nextPage">继续探索下一页 ↓</button>`:''}`}
async function museum(){if(!S.user)return guest('建造属于自己的世界','注册一个账号，便能发布展品、布置展厅，并向其他人公开展示。');const [mine,halls]=await Promise.all([api('/my/exhibits'),api('/my/halls')]);S.mine=mine;S.halls=halls;return `<div class="eyebrow">MY WORLD · PERSONAL MUSEUM</div><h1 class="page-title">${E(S.user.username)} 的万物博物馆</h1><p class="page-intro">收藏，是建造自己世界的第一步。所有私人展品只有你自己能看见。</p>
${usageGuide('我的博物馆怎么用',['添加展品：保存现实发现、网页链接、图片或原创想法。','创建展厅：按主题整理藏品，设置公开参观或仅自己可见。','进入展厅后可自由布展、沉浸参观；重要数据可导出备份。'])}
<div class="feature-box" style="margin-top:25px"><div><span class="eyebrow">THE CURATOR'S STUDIO</span><h2>我的世界，由我陈列。</h2><p>在这里组织自己的收藏，创建主题展厅，拖动展品布置位置，也可以邀请其他人来参观公开的展厅。</p><div class="row-actions"><button class="primary" data-action="new">＋ 添加展品</button><button class="ghost" data-action="newHall">＋ 创建展厅</button><button class="ghost" data-action="navigate" data-view="virtual-gallery">▧ 展厅工坊</button><button class="ghost" data-action="import">⇧ 导入旧版收藏</button><button class="ghost" data-action="export">⇩ 备份数据</button></div></div><div class="feature-symbol">❖</div></div>
${heading('ROOMS · COLLECTION SPACES','我的展厅',`已建立 ${halls.length} 个主题展厅 · 点击进入布展或参观`)}
${halls.length?`<div class="mini-halls">${halls.map(h=>`<button class="hall-card" data-action="hall" data-id="${h.id}"><div class="eyebrow">${h.visibility==='public'?'○ 公开参观':'◉ 私人展厅'}</div><h3>🏛 ${E(h.name)}</h3><p>${E(h.description||'进入展厅开始陈列')}　↗</p></button>`).join('')}</div>`:empty('没有展厅','先建造一座自己的展厅。')}
${heading('MY COLLECTION · ARCHIVE','我的全部展品',`${mine.length} 件收藏，包括公开与私密内容`)}
${mine.length?`<div class="card-grid">${mine.map(card).join('')}</div>`:empty('还没有自己的展品','把第一件让你感到有趣的事物放进万物博物馆。')}`}
function guest(title,desc){return `<div class="feature-box"><div><div class="eyebrow">YOUR WORLD IS WAITING</div><h2>${title}</h2><p>${desc}</p><button class="primary" data-action="login">登录 / 免费注册</button></div><div class="feature-symbol">✧</div></div>`}
async function saved(){if(!S.user)return guest('喜欢的事物，值得留存','创建账号之后，你可以把其他馆长的公开展品加入自己的心动清单。');S.saved=await api('/my/saved');return `<div class="eyebrow">HEART COLLECTION</div><h1 class="page-title">心动收藏</h1><p class="page-intro">这里专门保存你在浏览其他展品时收藏的有趣事物；它与自己发布的馆藏分开管理。</p>${usageGuide('心动收藏怎么用',['在任意公开展品详情中点击收藏。','回到这里继续查看，不必重新搜索。','原作者删除或设为私密后，相关内容可能不再公开可见。'])}<div style="height:22px"></div>${S.saved.length?`<div class="card-grid">${S.saved.map(card).join('')}</div>`:empty('暂时没有心动藏品','去探索大厅发现让你喜欢的东西。','<button class="primary" data-action="navigate" data-view="discover">探索公开展品</button>')}`}
async function journey(){if(!S.journey)S.journey=await api('/random');return `<div class="eyebrow">SERENDIPITY · UNKNOWN DISCOVERIES</div><h1 class="page-title">奇遇航线</h1><p class="page-intro">不用输入关键词，让一次随机点击带你走进陌生人的发现。</p>${usageGuide('随机奇遇怎么玩',['系统从当前服务器的公开展品中随机抽取一件。','点“走近这件展品”阅读档案，再决定是否收藏或继续探索。','点“下一次奇遇”换一个对象；没有公开投稿时不会生成虚构展品。'])}${S.journey?`<div class="journey-layout">${art(S.journey)}<div class="journey-copy"><div class="eyebrow">YOU HAVE DISCOVERED · ${E(S.journey.category)}</div><h2>${E(S.journey.title)}</h2><p>${E(S.journey.description||'这是一件值得继续了解的东西。')}</p><p class="muted">来自馆长：${E(S.journey.owner)}</p><div class="row-actions"><button class="primary" data-action="detail" data-id="${S.journey.id}">走近这件展品 ↗</button><button class="ghost" data-action="reroll">✧ 下一次奇遇</button></div></div></div>`:empty('奇遇正在酝酿','目前还没有任何公开展品。等有馆长投稿后，你就可以在这里随机探索。','<button class="ghost" data-action="navigate" data-view="discover">返回发现广场</button>')}`}
async function notifications(){if(!S.user)return guest('别人的发现，也会回应你','注册登录之后，可以收到点赞、评论以及新的关注提醒。');let n=await api('/notifications');$('#navUnread').textContent=n.unread||'';return `<div class="eyebrow">ACTIVITY · SOCIAL</div><div class="section-title"><div><h1 class="page-title">通知中心</h1><p>他人的点赞、评论和关注会显示在这里。</p></div><button class="ghost" data-action="markRead">全部标为已读</button></div>${usageGuide('通知中心怎么用',['点击用户名进入馆长主页。','点击“查看”跳转到相关展品。','全部标为已读只改变你的通知状态，不会删除原始互动。'])}<div class="block">${n.items.length?n.items.map(x=>`<div class="notice ${x.is_read?'':'unread'}"><span class="n-ico">${x.kind==='follow'?'♡':x.kind==='like'?'♥':'✉'}</span><div><button class="userlink" data-action="user" data-name="${E(x.actor)}">${E(x.actor)}</button> ${x.kind==='follow'?'关注了你':x.kind==='like'?'赞了你的展品':'评论了你的展品'} ${x.exhibit_id?`<button class="userlink" data-action="detail" data-id="${x.exhibit_id}">查看 ↗</button>`:''}</div><time>${E(x.created_at.slice(0,10))}</time></div>`).join(''):empty('这里还没有消息','发布展品并分享给朋友，会收到他们的互动提醒。')}</div>`}
async function profile(){if(!S.profile)return empty('未找到馆长');let d=await api('/users/'+encodeURIComponent(S.profile));S.profileData=d;return `<div class="eyebrow">CURATOR · PUBLIC MUSEUM</div><div class="feature-box" style="margin-top:15px"><div><span class="eyebrow">✧ 世界中的一位馆长</span><h2>${E(d.user.username)} 的世界</h2><p>${E(d.user.bio||'这位馆长还没有写介绍。')}</p><p class="muted">${d.items.length} 件可见展品 · ${d.followers} 位关注者 · 关注了 ${d.following} 人</p>${S.user&&S.user.id!==d.user.id?`<button class="primary" data-action="follow" data-id="${d.user.id}">${d.is_following?'✓ 已关注 · 点击取消':'＋ 关注馆长'}</button>`:''}${S.user&&S.user.id===d.user.id?`<button class="ghost" data-action="editBio">编辑个人介绍</button>`:''}</div><div class="feature-symbol">◈</div></div>
${usageGuide('参观这位馆长的世界',['公开展厅可以进入参观，查看馆主如何整理收藏。','下面只显示对你可见的公开展品。','登录后可以关注馆长，之后在发现广场查看关注动态。'])}${heading('OPEN ROOMS','开放展厅')}${d.halls.length?`<div class="mini-halls">${d.halls.map(h=>`<button class="hall-card" data-action="hall" data-id="${h.id}"><div class="eyebrow">PUBLIC MUSEUM ROOM</div><h3>${E(h.name)} ↗</h3><p>${E(h.description)}</p></button>`).join('')}</div>`:empty('暂无公开展厅')}
${heading('CONTRIBUTIONS','馆长的发现')}${d.items.length?`<div class="card-grid">${d.items.map(card).join('')}</div>`:empty('暂无公开展品')}`}
function showModal(title,body,wide=false){$('#modal').classList.remove('hidden');$('#modal').innerHTML=`<div class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="dialog-head"><h2>${E(title)}</h2><button class="xbtn" aria-label="关闭" data-action="close">×</button></div><div class="dialog-body">${body}</div></div>`}
function close(){const m=$('#modal');m.innerHTML='';m.classList.add('hidden');S.detail=null;S.editorId=null;S.editingRoom=null}
function openAccount(){showModal('我的账号',`<div class="eyebrow">SIGNED IN CURATOR</div><h2 class="page-title">◈ ${E(S.user.username)}</h2><p class="muted">你的藏品、展厅和账号信息都保存在当前运行的服务器中。</p><div class="row-actions"><button class="primary" data-action="accountMuseum">进入我的博物馆</button><button class="ghost danger" data-action="logout">退出登录</button></div>`)}
function openAuth(mode='login'){S.authMode=mode;showModal('欢迎来到万物博物馆',`<div class="login-tabs"><button class="ghost ${mode==='login'?'selected':''}" data-action="authMode" data-mode="login">登录</button><button class="ghost ${mode==='register'?'selected':''}" data-action="authMode" data-mode="register">注册新馆长</button></div><form id="authForm"><label class="form-row">馆长名字（3–24 字，可用中文、字母、数字和下划线）<input name="username" maxlength="24" minlength="3" autocomplete="username" required></label><label class="form-row">密码（至少 8 位）<input type="password" name="password" minlength="8" maxlength="128" autocomplete="${mode==='login'?'current-password':'new-password'}" required></label><div class="submit-row"><button type="submit" class="primary">${mode==='login'?'登录博物馆':'创建我的博物馆'}</button></div></form><p class="muted">${mode==='login'?'没有账号？点击上方注册。':'注册后会自动为你建立一间个人展厅。'} 你的公开展品会真正出现在其他用户的探索大厅里。</p>`) }
const frow=(name,label,value='',type='text',required=false)=>`<label class="form-row">${label}<input name="${name}" type="${type}" value="${E(value)}" ${required?'required':''}></label>`;
async function openEditor(id=null){if(!mustLogin())return;S.editorId=id;let x=id?await api('/exhibits/'+id):{title:'',description:'',story:'',category:'其他',series:'民间奇趣',domain:'其他',time_bucket:'时间不详',time_basis:'不详',time_note:'',tags:[],source_url:'',image_url:'',visibility:'public'};const categoryChoices=[...new Set([...(TAX.groups[x.domain]||TAX.groups['其他']),...(x.category&&!(TAX.groups[x.domain]||[]).includes(x.category)?[x.category]:[])])];const mine=id&&x.user_id===S.user.id;if(id&&!mine){toast('只能编辑自己的藏品');return}showModal(id?'编辑展品':'放入一件新展品',`<form id="exhibitForm"><div class="form-grid"><div class="wide">${frow('title','展品名称',x.title,'text',true)}</div><label class="form-row">大系列<select name="series">${TAX.series.map(v=>`<option value="${E(v)}" ${(x.series||'民间奇趣')===v?'selected':''}>${E(TAX.seriesLabels?.[v]||v)}</option>`).join('')}</select><small>藏品系列用于整理专题与来源明确的系列；用户上传系列收录你自己发现、上传或原创的有趣内容。旧版存储值保持兼容。</small></label><label class="form-row">主要领域<select name="domain">${TAX.domains.map(v=>`<option value="${E(v)}" ${(x.domain||'其他')===v?'selected':''}>${E(v)}</option>`).join('')}</select></label><label class="form-row">细分类别<select name="category">${categoryChoices.map(c=>`<option ${x.category===c?'selected':''}>${E(c)}</option>`).join('')}</select></label><label class="form-row">时代 / 时间尺度<select name="time_bucket">${TAX.timeBuckets.map(v=>`<option value="${E(v)}" ${(x.time_bucket||'时间不详')===v?'selected':''}>${E(v)}</option>`).join('')}</select></label><label class="form-row">时间依据<select name="time_basis">${TAX.timeBases.map(v=>`<option value="${E(v)}" ${(x.time_basis||'不详')===v?'selected':''}>${E(v)}</option>`).join('')}</select></label>${frow('time_note','具体年代 / 时间原文',x.time_note||'')}<div class="form-note wide">时间尺度用于快速筛选；具体年代尽量保留原始资料写法。化石填写形成时代，古画填写创作年代，热梗填写走红时间。</div><label class="form-row">可见性<select name="visibility"><option value="public" ${x.visibility==='public'?'selected':''}>公开 · 让所有馆长发现</option><option value="private" ${x.visibility==='private'?'selected':''}>私密 · 只有自己可见</option></select></label><label class="form-row wide">一句话介绍<input name="description" value="${E(x.description)}" maxlength="600" placeholder="为什么它有意思？"></label><label class="form-row wide">馆长手记 / 故事<textarea name="story" rows="5" maxlength="5000" placeholder="这个东西为什么值得收藏？">${E(x.story)}</textarea></label>${frow('tags','标签（用逗号隔开）',Array.isArray(x.tags)?x.tags.join(','):x.tags)}${frow('source_url','来源地址（可选）',x.source_url,'url')}${frow('image_url','封面图片链接（可选）',x.image_url)}<label class="form-row wide">或者上传一张封面图（最大 4 MB）<input id="coverFile" type="file" accept="image/jpeg,image/png,image/webp"><small>上传后会保存在服务器，并自动压缩。</small></label></div><div class="submit-row"><button class="ghost" type="button" data-action="close">取消</button><button class="primary" type="submit">${id?'保存修改':'发布 / 私藏'}</button></div></form>`)}
async function openDetail(id){let [x,comments,hub]=await Promise.all([api('/exhibits/'+id),api('/exhibits/'+id+'/comments'),api('/exhibits/'+id+'/hub')]);if(window.WonderMemories)WonderMemories.track(x);S.detail=x;const owner=S.user&&S.user.id===x.user_id;showModal('万物档案 / NO. '+String(x.id).padStart(5,'0'),`<div class="detail-layout">${art(x,'detail-art')}<div><div class="eyebrow">${x.visibility==='public'?'OPEN COLLECTION':'PRIVATE COLLECTION'} · ${E(x.category)}</div><h2 class="detail-title">${E(x.title)}</h2><p class="detail-copy">${E(x.description||'这是一件尚未添加简介的展品。')}</p><div class="detail-taxonomy"><button type="button" data-action="filterSeries" data-value="${E(x.series||'民间奇趣')}">系列：${E(TAX.seriesLabels?.[x.series||'民间奇趣']||x.series||'民间奇趣')}</button><button type="button" data-action="filterDomain" data-value="${E(x.domain||'其他')}">领域：${E(x.domain||'其他')}</button><button type="button" data-action="filterCategory" data-value="${E(x.category||'其他')}" data-domain="${E(x.domain||'其他')}">细类：${E(x.category||'其他')}</button><button type="button" data-action="filterTime" data-value="${E(x.time_bucket||'时间不详')}">时代：${E(x.time_bucket||'时间不详')}</button><span>时间依据：${E(x.time_basis||'不详')}</span><span>来源状态：${x.source_url?'已附来源':'尚未补充来源'}</span>${x.time_note?`<span>年代原文：${E(x.time_note)}</span>`:''}</div><div class="tags">${x.tags.map(t=>`<span class="tag"># ${E(t)}</span>`).join('')}</div><div class="detail-meta"><div>发现者　<button class="userlink" data-action="user" data-name="${E(x.owner)}">${E(x.owner)} ↗</button></div><div>展出日期　${E(x.created_at.slice(0,10))}</div>${x.source_url?`<div>资料来源　<a target="_blank" rel="noopener noreferrer" href="${E(x.source_url)}">打开原始链接 ↗</a></div>`:''}</div><div class="row-actions detail-core-actions" style="margin-top:19px">
<button class="ghost" data-action="like" data-id="${x.id}">${x.liked?'♥ 已点赞':'♡ 点赞'} (${x.likes_count})</button>
<button class="ghost" data-action="bookmark" data-id="${x.id}">${x.bookmarked?'✓ 已收藏':'♧ 收藏'}</button>
${x.visibility==='public'?wheelActions(x):''}
${owner?`<button class="ghost" data-action="edit" data-id="${x.id}">✎ 编辑藏品</button>`:''}
</div><details class="detail-nav-advanced"><summary>更多操作：星图、游戏、展厅与管理</summary><div class="row-actions">
${x.visibility==='public'?`<button class="ghost" data-action="atlasFrom" data-id="${x.id}">✧ 从这里跨界探索</button>`:''}
<button class="ghost" data-action="constellationAdd" data-id="${x.id}">✧ 加入我的万物星图</button>
<button class="ghost" data-cx="open" data-id="${x.id}">⌁ 分类与关联图</button>
<button class="ghost" data-action="cosmosFocus" data-id="${x.id}">⏳ 时光与证据</button>
${x.visibility==='public'?`<button class="ghost" data-action="playFrom" data-id="${x.id}">🔗 万物接力，从这里开始</button>`:''}
${owner?`<button class="ghost" data-action="pickHall" data-id="${x.id}">＋ 放入展厅</button><button class="ghost danger" data-action="delete" data-id="${x.id}">删除</button>`:`<button class="ghost" data-action="report" data-id="${x.id}">举报</button>`}
</div></details></div></div></div>
${x.story?`<div class="block"><div class="eyebrow">THE CURATOR'S STORY</div><p class="detail-copy">${E(x.story)}</p></div>`:''}
${window.WonderObjectHub?.render(hub)||''}
<div class="block"><div class="section-title" style="margin:0 0 15px"><div><div class="eyebrow">PUBLIC CONVERSATION</div><h2 style="font-size:23px">馆长留言 ${comments.length}</h2></div></div><div id="comments">${comments.length?comments.map(c=>`<div class="comment"><button class="userlink" data-action="user" data-name="${E(c.username)}">${E(c.username)}</button><time>${E(c.created_at.slice(0,16))}</time><p>${E(c.body)}</p></div>`).join(''):'<p class="muted">还没有留言，来写第一条吧。</p>'}</div>${x.visibility==='public'?`<form id="commentForm" class="comment-form"><input name="body" maxlength="600" required placeholder="写下你对这件展品的想法…"><button class="primary">发送留言</button></form>`:''}</div>`,true)}
async function openHall(id){S.room=await api('/halls/'+id);S.roomEditing=false;renderHall()}
function renderHall(){let r=S.room,h=r.hall,owner=!!(S.user&&h.user_id===S.user.id);let tiles=r.items.map(x=>`<div class="placed" data-id="${x.id}" style="left:${x.x}px;top:${x.y}px;width:${x.width}px" data-action="${owner&&S.roomEditing?'':'detail'}">${x.image_url?`<img src="${E(x.image_url)}" alt="">`:`<div class="bigglyph">${categoryGlyph(x)}</div>`}<label>${E(x.title)}</label></div>`).join('');showModal(h.name,`<div class="eyebrow">${h.visibility==='public'?'PUBLIC':'PRIVATE'} · ${E(h.theme.toUpperCase())} ROOM</div><p class="muted">${E(h.description||'每一件收藏都是这个世界的一块拼图。')}</p><div class="studio-toolbar"><div class="row-actions">${owner?`<button class="ghost" data-action="hallAdd" data-id="${h.id}">＋ 添加藏品</button><button class="ghost" data-action="hallEdit" data-id="${h.id}">⚙ 展厅设置</button><button class="ghost" data-action="toggleStudio">${S.roomEditing?'✓ 结束布展':'✥ 自由布展'}</button>`:''}<button class="ghost" data-action="tour" data-index="0" ${r.items.length?'':'disabled'}>▶ 沉浸参观</button></div><small class="muted">${S.roomEditing?'拖动卡片可改变位置，自动保存':'点击展品查看档案'}</small></div><div id="studioBoard" class="studio-board ${h.theme} ${S.roomEditing?'editing':''}">${tiles||'<div class="loading">展厅空空如也，等你来布置。</div>'}</div>${owner?`<div class="hall-list" style="margin-top:12px"><span class="muted">展厅藏品：</span>${r.items.map(x=>`<button class="ghost" data-action="roomRemove" data-id="${x.id}">移出 ${E(x.title)} ×</button>`).join('')}</div>`:''}`,true);if(owner&&S.roomEditing)installDrag()}
function installDrag(){const board=$('#studioBoard');let state=null;board.querySelectorAll('.placed').forEach(el=>{el.addEventListener('pointerdown',e=>{if(e.button!==0)return;state={el,sx:e.clientX,sy:e.clientY,x:parseFloat(el.style.left),y:parseFloat(el.style.top)};el.setPointerCapture(e.pointerId);e.preventDefault()});el.addEventListener('pointermove',e=>{if(!state||state.el!==el)return;let dx=e.clientX-state.sx,dy=e.clientY-state.sy;el.style.left=Math.min(850,Math.max(0,state.x+dx))+'px';el.style.top=Math.min(480,Math.max(0,state.y+dy))+'px'});el.addEventListener('pointerup',async e=>{if(!state)return;state=null;const positions=[...board.querySelectorAll('.placed')].map(e=>({exhibit_id:Number(e.dataset.id),x:Math.round(parseFloat(e.style.left)),y:Math.round(parseFloat(e.style.top)),width:Math.round(parseFloat(e.style.width))}));try{await api('/halls/'+S.room.hall.id+'/layout',{method:'PATCH',body:{positions}});S.room=await api('/halls/'+S.room.hall.id);toast('布展位置已保存')}catch(err){toast(err.message)}})})}
async function openTour(index){let items=S.room?.items||[];if(!items.length)return;index=(index+items.length)%items.length;S.tourIndex=index;let x=items[index];showModal('沉浸参观 · '+E(S.room.hall.name),`<div class="journey-layout">${art(x)}<div class="journey-copy"><div class="eyebrow">EXHIBIT ${index+1} / ${items.length}</div><h2>${E(x.title)}</h2><p>${E(x.description||x.story||'不必解释，静静欣赏。')}</p><div class="row-actions"><button class="ghost" data-action="tour" data-index="${index-1}">← 上一件</button><button class="ghost" data-action="detail" data-id="${x.id}">查看档案</button><button class="primary" data-action="tour" data-index="${index+1}">下一件 →</button></div><button class="ghost" style="margin-top:18px" data-action="hall" data-id="${S.room.hall.id}">返回展厅</button></div></div>`,true)}
async function openHallForm(id=null){if(!mustLogin())return;let h=id?S.halls.find(x=>x.id===id):null;S.editingRoom=id;showModal(id?'展厅设置':'创建一座展厅',`<form id="hallForm">${frow('name','展厅名称',h?.name||'', 'text',true)}<label class="form-row">展厅介绍<textarea name="description">${E(h?.description||'')}</textarea></label><div class="form-grid"><label class="form-row">展厅环境<select name="theme">${[['nebula','星云穹顶'],['gallery','经典美术馆'],['forest','森野植物园'],['sunset','落日档案馆']].map(([v,t])=>`<option value="${v}" ${h?.theme===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="form-row">展厅隐私<select name="visibility"><option value="public" ${h?.visibility!=='private'?'selected':''}>开放参观</option><option value="private" ${h?.visibility==='private'?'selected':''}>仅自己可见</option></select></label></div><div class="submit-row">${id?`<button type="button" class="ghost danger" data-action="deleteHall" data-id="${id}">删除展厅</button>`:''}<button class="primary">保存展厅</button></div></form>`)}
async function pickHall(id){if(!mustLogin())return;S.pickingId=id;let halls=await api('/my/halls');showModal('将藏品放入展厅',halls.length?`<p class="muted">点击一个展厅，将这件藏品陈列进去：</p><div class="mini-halls">${halls.map(h=>`<button class="hall-card" data-action="addToHall" data-id="${h.id}"><h3>${E(h.name)} ↗</h3><p>${E(h.description)}</p></button>`).join('')}</div>`:empty('先创建一座展厅','前往“我的博物馆”建立展厅，再摆放藏品。'))}
async function hallAdd(id){let mine=await api('/my/exhibits');S.pickingHall=id;showModal('添加藏品到展厅',mine.length?`<p class="muted">选择你要加入的个人展品</p><div class="card-grid">${mine.map(x=>`<div class="card" data-action="addItemHall" data-id="${x.id}">${art(x)}<div class="card-content"><h3>${E(x.title)}</h3></div></div>`).join('')}</div>`:empty('先发布一件展品'))}
function openImport(){if(!mustLogin())return;showModal('从 V1.0 本地收藏迁移',`<p class="muted">可选择 V1.0 本地备份或 V2.0 联网版备份。V1 只导入个人原创收藏；V2 恢复展品、展厅及布展位置（不导入其他人的账号、评论或点赞）。</p><div class="auth-note">V1 导入时所有展品默认为「私密」，旧版内嵌图片需要重新上传。V2 备份恢复时将保留展品可见性，请检查原设置。</div><form id="importForm"><label class="form-row">JSON 备份文件<input type="file" accept=".json,application/json" name="backup" required></label><button class="primary">导入我的收藏</button></form>`)}
async function exportMine(){let out=await api('/my/backup');let blob=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`wonder-${S.user.username}-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);toast('完整备份已保存，包含展品、展厅和布展位置')}

// Global click handling avoids binding duplicate button implementations across screens.
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b)return;if(b.closest('.card')&&b!==b.closest('.card')&&b.dataset.action==='detail')return;let a=b.dataset.action,id=Number(b.dataset.id||0);try{
if(a==='navigate')await navigate(b.dataset.view);
else if(a==='navBack')await navBack();
 else if(a==='searchPreset'){WonderSearch.setQuery(b.dataset.value||'');await navigate('search')}
 else if(a==='searchReset'){WonderSearch.reset();await render()}
 else if(a==='searchClearFacet'){WonderSearch.select(b.dataset.name,'全部');await render()}
 else if(a==='searchPage'){WonderSearch.nextPage(b.dataset.page);await render();window.scrollTo({top:0})}
else if(a==='taxonomyDomain'){S.q='';S.cat='全部';S.domain=b.dataset.value;S.series='全部';S.timeBucket='全部';S.following=false;S.page=1;await navigate('discover');}
else if(a==='taxonomyCategory'){S.q='';S.cat=b.dataset.value;S.domain=b.dataset.domain||'全部';S.series='全部';S.timeBucket='全部';S.following=false;S.page=1;await navigate('discover');}
else if(a==='taxonomyTime'){S.q='';S.cat='全部';S.domain='全部';S.series='全部';S.timeBucket=b.dataset.value;S.following=false;S.page=1;await navigate('discover');}
else if(a==='taxonomySeries'){S.q='';S.cat='全部';S.domain='全部';S.series=b.dataset.value;S.timeBucket='全部';S.following=false;S.page=1;await navigate('discover');}
else if(a==='taxonomyClear'){S.q='';S.cat='全部';S.domain='全部';S.series='全部';S.timeBucket='全部';S.following=false;S.page=1;if(S.view==='discover')await render();else await navigate('discover');}
else if(a==='filterDomain'||a==='filterCategory'||a==='filterTime'||a==='filterSeries'){const action=a,value=b.dataset.value,domain=b.dataset.domain;if(!$('#modal').classList.contains('hidden'))close();if(action==='filterDomain'){S.domain=value;S.cat='全部';}else if(action==='filterCategory'){S.cat=value;S.domain=domain||S.domain;}else if(action==='filterTime')S.timeBucket=value;else if(action==='filterSeries')S.series=value;S.q='';S.following=false;S.page=1;if(S.view==='discover')await render();else await navigate('discover');}
else if(a==='category'){S.cat=b.dataset.cat;S.page=1;await render()}
else if(a==='series'){S.series=b.dataset.series||'全部';S.page=1;await render()}
else if(a==='following'){if(!mustLogin())return;S.following=!S.following;S.page=1;await render()}
else if(a==='nextPage'){S.page+=1;await render();window.scrollTo({top:0})}
else if(a==='login')openAuth('login');
else if(a==='accountMuseum'){close();await navigate('museum')}
else if(a==='account')openAccount();
else if(a==='logout'){await api('/auth/logout',{method:'POST'});S.user=null;S.following=false;S.profile=null;S.journey=null;close();navMark();await navigate('discover');refreshUnread();toast('已经退出登录')}
else if(a==='authMode')openAuth(b.dataset.mode);
else if(a==='close')close();
else if(a==='reload')await init();
else if(a==='new')await openEditor();
else if(a==='detail'){window.WonderObjectHub?.reset();trackUsage('discover','detail');await openDetail(id);}
else if(a==='hubDetail'){const from=S.detail;if(!from)return;if(!Number.isSafeInteger(id)||id<1||id===from.id)return;window.WonderObjectHub?.push(from.id,from.title);try{await openDetail(id)}catch(err){window.WonderObjectHub?.pop();throw err}}
else if(a==='hubBack'){const prev=window.WonderObjectHub?.pop();if(prev)await openDetail(prev.id);}
else if(a==='copyExhibit'){if(S.detail?.id!==id)return;const url=new URL(window.location.href);url.search='';url.hash='';url.searchParams.set('source',String(id));if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(url.href);toast('已复制原始藏品链接；公开状态变化后链接可能不可访问。')}catch(err){window.prompt('复制原始藏品链接',url.href)}}else window.prompt('复制原始藏品链接',url.href)}
else if(a==='edit')await openEditor(id);
else if(a==='like'||a==='bookmark'){if(!mustLogin())return;await api('/exhibits/'+id+'/'+a,{method:'POST'});trackUsage('discover',a==='like'?'like':'save');await openDetail(id)}
else if(a==='delete'){if(!confirm('确定要永久删除这件展品吗？'))return;await api('/exhibits/'+id,{method:'DELETE'});close();toast('展品已删除');await render()}
else if(a==='report'){if(!mustLogin())return;let reason=prompt('请简要说明举报理由（至少5字）：');if(reason){await api('/exhibits/'+id+'/report',{method:'POST',body:{reason}});toast('举报已收到，感谢反馈')}}
else if(a==='user'){S.profile=b.dataset.name;close();await navigate('profile')}
else if(a==='follow'){if(!mustLogin())return;await api('/users/'+id+'/follow',{method:'POST'});await render()}
else if(a==='cosmosFocus'){close();WonderCosmos.focus(id)}
else if(a==='wheelFrom'){const chosen=S.detail;const topic=b.dataset.topic||'';close();window.WonderWheel?.queueExhibit(id,chosen?.title||'',topic);await navigate('wheels')}
else if(a==='playFrom'){const chosen=S.detail;close();window.WonderPlay?.startFromExhibit(id,chosen?.title||'');await navigate('play')}
else if(a==='atlasFrom'){close();const found=await WonderAtlas.startFrom('post:'+id);if(!found){toast('当前投稿暂时不在可检索范围');return}await navigate('journey')}else if(a==='constellationAdd'){if(!mustLogin())return;await api('/constellation/nodes',{method:'POST',body:{kind:'exhibit',exhibit_id:id}});close();toast('已加入你的私人万物星图');await navigate('constellation')}
else if(a==='reroll'){S.journey=await api('/random');trackUsage('random_journey','complete');await render()}
else if(a==='newHall'){trackUsage('hall_builder','create');await openHallForm();}
else if(a==='hall')await openHall(id);
else if(a==='hallEdit')await openHallForm(id);
else if(a==='hallAdd')await hallAdd(id);
else if(a==='pickHall')await pickHall(id);
else if(a==='addToHall'){await api('/halls/'+id+'/items',{method:'POST',body:{exhibit_id:S.pickingId}});toast('藏品已陈列到展厅');close()}
else if(a==='addItemHall'){await api('/halls/'+S.pickingHall+'/items',{method:'POST',body:{exhibit_id:id}});toast('展品已加入展厅');await openHall(S.pickingHall)}
else if(a==='roomRemove'){await api('/halls/'+S.room.hall.id+'/items/'+id,{method:'DELETE'});await openHall(S.room.hall.id)}
else if(a==='toggleStudio'){S.roomEditing=!S.roomEditing;renderHall()}
else if(a==='tour'){trackUsage('hall_builder','play');await openTour(Number(b.dataset.index));}
else if(a==='deleteHall'){if(!confirm('确定删除展厅？藏品本身不会被删除。'))return;await api('/halls/'+id,{method:'DELETE'});close();toast('展厅已删除');await navigate('museum')}
else if(a==='markRead'){await api('/notifications/read',{method:'POST'});await refreshUnread();await render()}
else if(a==='editBio')showModal('修改个人介绍',`<form id="bioForm"><label class="form-row">介绍<textarea maxlength="240" name="bio">${E(S.profileData.user.bio)}</textarea></label><button class="primary">保存</button></form>`);
else if(a==='import')openImport();
else if(a==='export')await exportMine();
}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{let form=e.target;const type=form.id;if(!['authForm','exhibitForm','hallForm','commentForm','searchForm','unifiedSearchForm','bioForm','importForm'].includes(type))return;e.preventDefault();const btn=form.querySelector('[type=submit],button:not([type])');if(btn)btn.disabled=true;let fd=new FormData(form);let data=Object.fromEntries(fd.entries());try{
if(type==='authForm'){S.user=await api('/auth/'+S.authMode,{method:'POST',body:{username:data.username,password:data.password}});close();navMark();await navigate('museum');refreshUnread();toast(S.authMode==='register'?'欢迎成为万物博物馆的新馆长！':'欢迎回来！')}
if(type==='searchForm'){S.q=data.q||'';S.sort=data.sort;S.cat=data.categoryFilter||'全部';S.domain=data.domainFilter||'全部';S.timeBucket=data.timeBucketFilter||'全部';S.page=1;if(S.q.trim()){WonderSearch.setQuery(S.q);WonderSearch.select('domain',S.domain);WonderSearch.select('category',S.cat);WonderSearch.select('time_bucket',S.timeBucket);WonderSearch.select('series',S.series);await navigate('search')}else await render()}
 if(type==='unifiedSearchForm'){WonderSearch.fromForm(form);await render()}
if(type==='commentForm'){if(!mustLogin())return;await api('/exhibits/'+S.detail.id+'/comments',{method:'POST',body:{body:data.body}});await openDetail(S.detail.id);toast('留言已发表')}
if(type==='exhibitForm'){let file=$('#coverFile')?.files?.[0];if(file){let upload=new FormData();upload.append('file',file);data.image_url=(await api('/media',{method:'POST',form:upload})).url}delete data.file;let id=S.editorId;let result=await api(id?'/exhibits/'+id:'/exhibits',{method:id?'PATCH':'POST',body:data});close();toast('你的发现已经保存！');await navigate('museum');if(!id)await openDetail(result.id)}
if(type==='hallForm'){let id=S.editingRoom;await api(id?'/halls/'+id:'/halls',{method:id?'PATCH':'POST',body:data});close();toast('展厅已保存');await navigate('museum')}
if(type==='bioForm'){await api('/me',{method:'PATCH',body:{bio:data.bio}});close();await render();toast('介绍已更新')}
if(type==='importForm'){let file=form.querySelector('input[type=file]').files[0];if(!file||file.size>12*1024*1024)throw Error('请选择不超过12MB的 JSON 备份');let content=JSON.parse(await file.text());let v2=content.format==='wonder-atlas-network-v2';let result=await api(v2?'/import/v2':'/import/v1',{method:'POST',body:content});close();toast(v2?`恢复了 ${result.mapped_exhibits} 件展品和 ${result.created_halls} 个展厅`:`成功迁入 ${result.imported} 件私密展品`);await navigate('museum')}
}catch(err){toast(err.message);if(btn)btn.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id!=='featureSearch')return;const q=e.target.value.trim().toLocaleLowerCase();let count=0;document.querySelectorAll('[data-feature-card]').forEach(card=>{const match=!q||(card.dataset.featureSearch||'').toLocaleLowerCase().includes(q);card.hidden=!match;if(match)count++});document.querySelectorAll('[data-feature-group]').forEach(group=>{group.hidden=!group.querySelector('[data-feature-card]:not([hidden])')});const empty=$('#featureNoResults');if(empty)empty.hidden=count>0;});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'')){e.preventDefault();navigate('search').then(()=>document.querySelector('#unifiedSearchForm [name=q]')?.focus())}});
document.addEventListener('change',e=>{if(e.target.name==='domain'&&e.target.closest('#exhibitForm')){const form=e.target.form,cat=form?.querySelector('[name="category"]');if(!cat)return;const choices=TAX.groups[e.target.value]||TAX.groups['其他'];const current=cat.value;cat.innerHTML=choices.map(v=>`<option>${E(v)}</option>`).join('');cat.value=choices.includes(current)?current:(choices[0]||'其他');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').classList.contains('hidden'))close();if((e.key==='Enter'||e.key===' ')&&e.target.matches('.card[data-action="detail"]')){e.preventDefault();e.target.click()}});
$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')close()});
